"""니콜라 페페 설명(NOTE) 문장. build_pepe.py가 숫자를 넘겨 부른다."""

def d_(s):
    y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"

OPP_KO = {"FC Metz": "메스", "Amiens SC": "아미앵", "Olympique Marseille": "마르세유", "Dijon FCO": "디종",
          "Paris Saint-Germain": "PSG", "Stade Reims": "랭스", "FC Nantes": "낭트", "Angers SCO": "앙제",
          "Aston Villa": "애스턴 빌라", "Sheffield United": "셰필드 유나이티드", "Everton FC": "에버턴",
          "Villarreal CF": "비야레알", "LOSC Lille": "릴", "Olympique Lyon": "리옹", "Real Oviedo": "레알 오비에도"}

def make_note(v):
    M, E, ST, CK, X, S, EXC = v["M"], v["E"], v["ST"], v["CLUB_KO"], v["EXCL_CNT"], v["SRC"], v["EXC"]
    c3 = lambda x: "·".join(map(str, x[:3]))
    import collections
    pc = collections.Counter((r[9], r[1]) for r in E if r[8])
    pk = ", ".join(d_(d) + " " + OPP_KO[o] + "전" + (f" {n}개" if n > 1 else "") for (d, o), n in sorted(pc.items()))
    L = [
        f"니콜라 페페(앙제·릴·아스널·OGC 니스·트라브존스포르·비야레알)의 클럽 공식 경기 {v['NG']}경기({d_(M[0][0])} 아를아비뇽전 ~ {d_(M[-1][0])} 헤타페전)에서 나온 {v['NGo']}골 {v['NA']}도움(PK 골 {v['NPK']}개), 친선경기·코트디부아르 대표팀·2군(앙제 B)·아마추어 리그 시즌(스타드 푸아트뱅, US 오를레앙) 경기 제외",
        "클럽별 경기·골·도움: " + ", ".join(f"{CK[k]} {c3(x)}" for k, x in ST.items()) + f". 출전 분 합계 {v['MIN_TOT']:,}분",
        f"사용자 기준(소속 팀이 공식 프로 리그에 있던 시즌만 셈)에 따라 US 오를레앙 임대 2015-16(프랑스 3부 나시오날) {EXC['n']}경기 {EXC['g']}골 {EXC['a']}도움(리그 {EXC['lg']}경기 {EXC['lgg']}골, 쿠프 드 프랑스 4경기 3골, 쿠프 드 라 리그 1경기; PK 골 {EXC['pk']}개, Transfermarkt 기준)을 뺌. 스타드 푸아트뱅 2012-13(프랑스 5부 CFA 2; 영어 위키백과·FotMob 9경기 2골, Transfermarkt는 출전 기록 없음)과 앙제 B 2013-15(2군, 41경기 9골)도 넣지 않음. 앙제 2014-15는 리그2(프로 리그)라 넣음",
        f"출처: 경기 목록·출전 분(연장·퇴장 반영)은 Transfermarkt 선수 경기 성적, 골 시간·골 뒤 스코어·PK·도움은 Transfermarkt 경기 리포트를 쓰고 FotMob 경기 이벤트(골·도움이 있는 경기)와 대조함. 출전 분은 모두 Transfermarkt 그대로(90분 추정 없음, FotMob은 90분 경기를 89분으로 적는 경우가 많음)",
        "경기 수·골은 영어 위키백과 클럽·시즌·대회별 기록과 같고 두 곳만 다름: 앙제 2014-15 쿠프 드 프랑스(영어 위키백과에 줄 없음; Transfermarkt·프랑스어 위키백과 2경기 3골 — 2014.11.15 아르장트레전 3골, 2014.12.6 디낭전)는 Transfermarkt대로 넣음, 릴 2018-19 쿠프 드 프랑스(영어 위키백과 3경기, Transfermarkt·프랑스어 위키백과 2경기)는 Transfermarkt대로 2경기",
        "골: 골은 Transfermarkt와 FotMob이 수·분·PK 여부가 모두 같음(2014.11.15 아르장트레전 3골은 FotMob 경기 자료가 없어 Transfermarkt만). PK 골: " + pk,
        f"도움: Transfermarkt 리포트 도움 중 FotMob 경기 이벤트도 페페 도움으로 적은 것 + 다른 출처 2곳이 확인한 것. 도움 {v['NA']} = Transfermarkt 리포트 {v['N_TM_A']} − PK 유도 {X['PK 유도']}(2018.9.30 마르세유전 밤바 골, 2022.10.9 트루아전 들로르 골, 2026.1.31 오사수나전 헤라르드 모레노 골, 2026.5.24 아틀레티코 마드리드전 파레호 골) − 개별 판정 {X['개별 판정']}. 본인이 얻은 PK를 본인이 넣어 도움 칸에 본인 이름이 적힌 {X['본인 도움']}개(2017.11.5 메스전, 2018.9.15 아미앵전 2개, 2018.9.30 마르세유전, 2022.8.31 릴전)는 처음부터 도움으로 세지 않음",
        "FotMob에 없지만 다른 출처 2곳 이상이 페페 도움으로 적어 넣은 3개: 2018.3.2 니스전 51분 루이스 아라우주 골(OGC 니스 구단 경기 기사·Maxifoot 기사), 2019.1.7 소쇼전(쿠프 드 프랑스) 40분 루이스 아라우주 골(worldfootball·LiveSoccerTV 경기 기록), 2021.8.25 웨스트 브로미치전(리그컵) 69분 라카제트 골(Sky Sports 경기 기록·Eurosport 문자 중계·Yahoo 기사)",
        "개별 판정으로 뺀 도움 2개(Transfermarkt에만 있고 다른 출처로 확인 못 함): 2018.1.6 르망전(쿠프 드 프랑스) 90+6분 티아구 멘드스 골(fbref 골 기록표 한 곳뿐), 2023.11.10 콘야스포르전 59분 오누아추 골(FotMob·worldfootball 모두 도움 없음). FotMob에만 있는 도움 1개(2018.4.28 메스전 77분 비수마 골, Transfermarkt는 모티바 도움)도 다른 출처가 없어 넣지 않음",
        "도움 합계 비교: Transfermarkt 64(오를레앙 2개 제외)·FotMob 경력 합계 56·프랑스어 위키백과 59(오를레앙 제외)·이 계산기 " + str(v["NA"]),
        "날짜는 현지 날짜(Transfermarkt 리포트·일정 날짜, 모든 경기가 유럽)",
        f"상대 Elo는 같은 경기를 다룬 다른 선수 자료(피에르에메릭 오바메양·알렉상드르 라카제트·부카요 사카·메수트 외질) 값, 같은 팀·같은 시즌 다른 선수 자료 값, 그 시즌 최종 순위에 맞춘 리그 값, 직접 추정 순으로 씀(기록 {len(E)}개: 같은 경기 {S['같은 경기 다른 선수 자료']}, 같은 팀·시즌 {S['팀×시즌 통합표']}, 순위+리그 값 {S['순위표+리그 값']}, 직접 {S['직접 추정']})",
        "순위+리그 값: 소쇼 2018-19 리그2 16위 1499(다른 선수 자료 리그2 15위·17위 값의 가운데), 비토리아 기마랑이스 2019-20 포르투갈 1부 7위 1627, 선덜랜드 2021-22 리그 원 5위 1530, 페네르바체 2023-24 쉬페르리그 2위 1764(같은 시즌 다른 순위 값에 맞춘 튀르키예 리그 곡선), 베식타시 2023-24 쉬페르리그 6위 1629(5위·7위 값의 가운데), 데포르티보 라코루냐 2026-27 라리가 9위 1767(진행 중, 11월 초 순위). 순위는 Transfermarkt 최종 순위표와 위키백과로 확인",
        "직접 추정(모두 '추정'): 아르장트레 2014-15(프랑스 아마추어 지역 리그) 1000, 르망 2017-18(프랑스 4부 나시오날 2) 1220, 던독 2020(아일랜드 3위) 1300, 슬로바츠코 2022-23(체코 5위) 1460, 파르티잔 2022-23(세르비아 4위) 1450, 마나코르 2026-27(스페인 5부) 1100",
        "대회 비중: 쿠프 드 프랑스·쿠프 드 라 리그·FA컵·리그컵·튀르키예컵·코파 델 레이는 국내컵(16강까지 낮은 비중, 8강 이후 높은 비중), 2025-26 이후 챔스 리그 단계는 조별과 같게, 유로파 32강(intermediate stage)은 유로파 토너먼트로 계산함. 컨퍼런스리그는 조별·토너먼트 구분",
        f"두 경기 합산(유로파 8강·준결승) 기록 {v['NTIE']}개({v['NTIEG']}경기)는 합산 S로 계산함(원정 다득점은 2020-21까지 적용). 승부차기로 끝난 2020.10.1 리버풀전(리그컵, 0:0 뒤 승부차기)과 2025.12.3 안토니아노전(코파 델 레이, 연장 1:1 뒤 승부차기)은 Transfermarkt 스코어가 승부차기 점수라 FotMob 정규·연장 스코어로 확인함(두 경기 모두 페페 골·도움 없음)",
        "시즌 구분은 모든 클럽 8월 1일 기준(아스널 2020.7~8월 경기는 2019-20). 클럽 구분은 2017.7.1 전 앙제(오를레앙 임대 기간 경기는 제외), 2019.8.1 전 릴, 2022.8.25 전 아스널, 2023.9.8 전 OGC 니스(임대, 2023년 여름 아스널 복귀 뒤 출전 없음), 2024.8.4 전 트라브존스포르, 이후 비야레알",
        "수상 기록은 Transfermarkt 업적 페이지 기준: FA컵 2020, 커뮤니티 실드 2020-21(Transfermarkt 표기 그대로, 이 경기 출전 기록은 없음). 쿠프 드 프랑스 2017(앙제)·튀르키예컵 2024(트라브존스포르) 준우승은 Transfermarkt 업적 페이지에 없어 넣지 않음. 아프리카 네이션스컵 2024 우승 등 대표팀 기록은 뺌",
        f"2026.11.13 기준 현역(비야레알, 2026-27 시즌 진행 중). 마지막 반영 경기 {d_(M[-1][0])} 헤타페전(2026.11.13 수집)",
    ]
    return "\n".join(L)
